package fr.noxodev.noxoclaim.gui;
import fr.noxodev.noxoclaim.NoxoClaim; import org.bukkit.*; import org.bukkit.entity.Player; import org.bukkit.event.*; import org.bukkit.event.inventory.InventoryClickEvent; import org.bukkit.inventory.*; import org.bukkit.inventory.meta.ItemMeta; import java.util.*;
public final class ClaimGui implements Listener {private final NoxoClaim p;public ClaimGui(NoxoClaim p){this.p=p;p.getServer().getPluginManager().registerEvents(this,p);}public void open(Player x){Inventory i=Bukkit.createInventory(null,27,"§8NoxoClaim");item(i,10,Material.GOLDEN_SHOVEL,"§bWand",List.of("§7Obtenir la wand de sélection"));item(i,13,Material.BOOK,"§bInfos",List.of("§7Informations sur le claim actuel"));item(i,16,Material.REDSTONE_BLOCK,"§cSupprimer",List.of("§7Supprimer votre claim actuel"));x.openInventory(i);}private void item(Inventory i,int s,Material m,String n,List<String> l){ItemStack a=new ItemStack(m);ItemMeta q=a.getItemMeta();q.setDisplayName(n);q.setLore(l);a.setItemMeta(q);i.setItem(s,a);}@EventHandler public void click(InventoryClickEvent e){if(!e.getView().getTitle().equals("§8NoxoClaim"))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player x))return;switch(e.getSlot()){case 10->x.performCommand("claim wand");case 13->x.performCommand("claim info");case 16->x.performCommand("claim delete");}}}
